static int tcpip_stack_run_ep(tcpip_stack_system_t *sys, int64_t now_ms, int hook_kind, int mod_id, int slot, int event, const fsa_val_t *args, int nargs) {
    if (!sys) return -FSA_ERR_INVALID_ARG;
    (void)hook_kind;
    if (hook_kind == 1) {
        (void)tcpip_stack_step_mod(sys, TCPIP_STACK_MOD_STACK_ACTOR, 0, now_ms, FSA_STACK_ACTOR_EV_ACTOR_POST_RX, NULL, 0);
        (void)tcpip_stack_step_mod(sys, TCPIP_STACK_MOD_STACK_ACTOR, 0, now_ms, FSA_STACK_ACTOR_EV_ACTOR_DISPATCH, NULL, 0);
    } else if (hook_kind == 2) {
        (void)tcpip_stack_step_mod(sys, TCPIP_STACK_MOD_STACK_ACTOR, 0, now_ms, FSA_STACK_ACTOR_EV_ACTOR_POST_API, NULL, 0);
        (void)tcpip_stack_step_mod(sys, TCPIP_STACK_MOD_STACK_ACTOR, 0, now_ms, FSA_STACK_ACTOR_EV_ACTOR_DISPATCH, NULL, 0);
    }
    int rc = tcpip_stack_step_mod(sys, mod_id, slot, now_ms, event, args, nargs);
    if (rc == FSA_OK) tcpip_stack_drain_bus(sys, now_ms);
    if (hook_kind != 0) {
        (void)tcpip_stack_step_mod(sys, TCPIP_STACK_MOD_STACK_ACTOR, 0, now_ms, FSA_STACK_ACTOR_EV_ACTOR_COMPLETE, NULL, 0);
    }
    return rc;
}

